!-----------------------------------------------------------------------------
!> @brief Contains forcing terms for the Haus-heating idealised Venus
!>        temperature forcing.
!>
!> @details Temperature follows
!!            dT/dt = (q - q_mean)/cp - (T - T_ref)/tau,
!!          with q a prescribed specific solar heating that moves with the
!!          Sun, q_mean its global and 24-hour mean at the same pressure,
!!          T_ref a horizontally uniform reference profile and tau a
!!          radiative relaxation time. Subtracting q_mean leaves only
!!          day-night and equator-pole contrasts in the solar term, so the
!!          global-mean equilibrium profile is T_ref whatever tau is, and the
!!          global-mean energy budget closes; q_mean stands in for the
!!          infrared cooling that balances solar heating on Venus.
!!
!!          q is tabulated from the net solar fluxes of Haus et al. (2016),
!!          as distributed with the LMD Venus PCM. The group's radiative
!!          transfer model is described in Haus, R., Kappel, D. and Arnold, G.
!!          (2015), Radiative heating and cooling in the middle and lower
!!          atmosphere of Venus, Planet. Space Sci., 117, 262-294. The PCM's
!!          flux table holds half the physical values; the factor of 2 is
!!          applied here. q is g dF/dp on the layers between the flux levels
!!          up to 100 km, by latitude and by hour angle from noon (0 to 90
!!          degrees, zero obliquity), and zero on the night side. The flux
!!          reaching the ground is spread uniformly by mass over the layers
!!          below 10 km, since the model has no surface to absorb it.
!!
!!          tau follows the Newtonian-cooling relaxation time of Crisp, D.
!!          (1989), Radiative forcing of the Venus mesosphere II, Icarus, 77,
!!          391-413, Fig. 12, above 60 km, and rises log-linearly to 2000
!!          Earth days at 45 km and below. No radiative estimate constrains
!!          tau below the clouds; 2000 days gives deep equator-pole contrasts
!!          like those of Lee et al. (2007) for this heating.
!!
!!          T_ref is the horizontal-mean profile T_Z(eta), eta = p/p_surf,
!!          of Lee, C., Lewis, S. R. and Read, P. L. (2007), J. Geophys. Res.,
!!          112, E04S11, eq. 5. The coefficient signs of T_Z are not legible
!!          in the published text; those here reproduce the 31-level T_Z
!!          table of the LMD Venus PCM to within 1E-3 K.
!!
!!          The sub-solar point moves eastward at Omega_orb - omega, with
!!          omega the planet's (retrograde, negative) rotation rate, giving a
!!          solar day of 116.75 Earth days for Venus. Tables are clamped at
!!          their end values outside their pressure and latitude ranges.
!!
!!          The tables are generated offline by haus_heating_table.py.
!>
module venus_heating_forcings_mod

  use constants_mod,     only: i_def, r_def, pi
  use planet_config_mod, only: omega

  implicit none

  private

  public :: venus_heating_terms
  public :: venus_heating_reference_temperature
  public :: venus_subsolar_longitude

  !> Orbital angular velocity of Venus (s-1): one orbit per 224.70 Earth days.
  real(kind=r_def), parameter :: omega_orb = &
                                 2.0_r_def*pi / (224.70_r_def * 86400.0_r_def)

  !> Spacing of the hour angles in q_tab (degrees).
  real(kind=r_def), parameter :: dhour_tab = 15.0_r_def

  !> Coefficients of T_Z (K) in powers of log10(eta), lowest power first.
  real(kind=r_def), parameter :: t_z_coeffs(0:5) = (/ &
       733.4861_r_def, 301.2670_r_def,  47.2002_r_def, &
        -5.0230_r_def,  -2.3257_r_def,  -0.1896_r_def /)

  !> Smallest eta for which T_Z is fitted (top of Lee's Table 1).
  real(kind=r_def), parameter :: eta_min = 2.265E-6_r_def

  !> Number of layers in the tables.
  integer(kind=i_def), parameter :: nlay = 83
  !> Number of hour angles in q_tab: 0 to 90 degrees from noon.
  integer(kind=i_def), parameter :: nhour = 7
  !> Number of latitudes in q_tab.
  integer(kind=i_def), parameter :: nlat = 19

