contains

!> @brief Heating terms at a point.
!> @param[in]  pressure    Pressure (Pa)
!> @param[in]  lat         Latitude (radians)
!> @param[in]  hour_angle  Longitude east of the sub-solar point (radians),
!>                         in [-pi, pi]
!> @param[out] q           Specific solar heating (W kg-1)
!> @param[out] q_mean      Global and 24-hour mean of q at this pressure (W kg-1)
!> @param[out] tau         Radiative relaxation time (s)
subroutine venus_heating_terms(pressure, lat, hour_angle, q, q_mean, tau)

  implicit none

  ! Arguments
  real(kind=r_def), intent(in)  :: pressure, lat, hour_angle
  real(kind=r_def), intent(out) :: q, q_mean, tau

  ! Local variables
  integer(kind=i_def) :: k, j, ih
  real(kind=r_def)    :: x, wp, lat_deg, wl, h_deg, wh, q_lo, q_hi
  real(kind=r_def)    :: q_k(2)

  ! Pressure index and weight; the table is small and ascending, so a
  ! linear scan is adequate here.
  x = log10(pressure)
  if (x <= log10_p_tab(1)) then
    k = 1_i_def
    wp = 0.0_r_def
  else if (x >= log10_p_tab(nlay)) then
    k = nlay - 1_i_def
    wp = 1.0_r_def
  else
    k = 1_i_def
    do while (x > log10_p_tab(k+1))
      k = k + 1_i_def
    end do
    wp = (x - log10_p_tab(k)) / (log10_p_tab(k+1) - log10_p_tab(k))
  end if

  q_mean = q_mean_tab(k) + wp*(q_mean_tab(k+1) - q_mean_tab(k))
  tau    = tau_tab(k)    + wp*(tau_tab(k+1)    - tau_tab(k))

  h_deg = abs(hour_angle) * 180.0_r_def / pi
  if (h_deg > 90.0_r_def) then
    q = 0.0_r_def
    return
  end if

  ! Latitude index and weight; the table is symmetric about the equator.
  lat_deg = abs(lat) * 180.0_r_def / pi
  if (lat_deg >= lat_tab(nlat)) then
    j = nlat - 1_i_def
    wl = 1.0_r_def
  else
    j = 1_i_def
    do while (lat_deg > lat_tab(j+1))
      j = j + 1_i_def
    end do
    wl = (lat_deg - lat_tab(j)) / (lat_tab(j+1) - lat_tab(j))
  end if

  ! Hour-angle index and weight.
  ih = min(1_i_def + int(h_deg / dhour_tab, i_def), nhour - 1_i_def)
  wh = (h_deg - dhour_tab*real(ih - 1_i_def, r_def)) / dhour_tab

  q_k(1) = q_tab(k,ih,j)   + wh*(q_tab(k,ih+1,j)   - q_tab(k,ih,j))
  q_k(2) = q_tab(k+1,ih,j) + wh*(q_tab(k+1,ih+1,j) - q_tab(k+1,ih,j))
  q_lo = q_k(1) + wp*(q_k(2) - q_k(1))

  q_k(1) = q_tab(k,ih,j+1)   + wh*(q_tab(k,ih+1,j+1)   - q_tab(k,ih,j+1))
  q_k(2) = q_tab(k+1,ih,j+1) + wh*(q_tab(k+1,ih+1,j+1) - q_tab(k+1,ih,j+1))
  q_hi = q_k(1) + wp*(q_k(2) - q_k(1))

  q = q_lo + wl*(q_hi - q_lo)

end subroutine venus_heating_terms

!> @brief Reference temperature T_Z of Lee et al. (2007).
!> @param[in] eta     Pressure divided by surface pressure
!> @return    t_ref   Reference temperature (K)
function venus_heating_reference_temperature(eta) result(t_ref)

  implicit none

  ! Arguments
  real(kind=r_def), intent(in) :: eta

  ! Local variables
  integer(kind=i_def) :: i
  real(kind=r_def)    :: x, t_ref

  x = log10(max(eta, eta_min))

  t_ref = 0.0_r_def
  do i = 5, 0, -1
    t_ref = t_ref*x + t_z_coeffs(i)
  end do

end function venus_heating_reference_temperature

!> @brief Longitude of the sub-solar point, zero at the start of the run.
!> @param[in] time      Model time (s)
!> @return    lon_sun   Sub-solar longitude (radians), in [0, 2*pi)
function venus_subsolar_longitude(time) result(lon_sun)

  implicit none

  ! Arguments
  real(kind=r_def), intent(in) :: time

  ! Local variables
  real(kind=r_def) :: lon_sun

  lon_sun = modulo((omega_orb - omega)*time, 2.0_r_def*pi)

end function venus_subsolar_longitude

end module venus_heating_forcings_mod
